{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C01", "C02", "C03", "C04", "C06", "C07", "C08", "C09", "C10",
    "C11", "C12", "C13", "C14", "C15", "C16", "C17", "C19", "C20",
    "C21", "C22", "C23", "C26", "C27", "C33", "C35", "C38", "C48",
    "C53", "C54", "C65", "C78"
  ],
  "contradictory_card_ids": ["C24", "C28"],
  "prediction_basis_card_ids": ["C01", "C10", "C33", "C48", "C53", "C65"],
  "claims": [
    {
      "claim": "All quantitative L1/L2 absolute-bioavailability values in the visible contexts are above the 20% threshold; the lowest measured values are haloperidol 35±8% (C08, C16) and ebastine about 40% (C02), while safinamide ~95% (C01, C10), encainide 76–78% (C06, C07, C14), ketanserin 49–60% (C12, C15), vernakalant 58–71% (C11, C13), GSK1322322 77% (C04), and ONO-4641 predicted 0.71 (C09, C17) are all higher.",
      "card_ids": ["C01", "C02", "C03", "C04", "C06", "C07", "C08", "C09", "C10", "C11", "C12", "C13", "C14", "C15", "C16", "C17"]
    },
    {
      "claim": "L3 oral-exposure records for the closest structural analogs, mosapride (M07) and renzapride (M17), show measurable systemic exposure after oral dosing: mosapride 5 mg geometric mean Cmax 23.13 ng/ml and AUC0-inf 74.05 ng·h/ml (C48, C65; also C33, C35, C38, C54, C78), and renzapride 1 mg Cmax 2.41 ng/ml (C53). This supports oral absorption for the same 4-amino-5-chloro-benzamide scaffold.",
      "card_ids": ["C33", "C35", "C38", "C48", "C53", "C54", "C65", "C78"]
    },
    {
      "claim": "No L3 card provides a direct absolute F for the query or a close analog, and AUC/Cmax values alone are not threshold-specific; they do not affirm F<20%.",
      "card_ids": ["C33", "C48", "C53", "C65"]
    },
    {
      "claim": "The only negative qualitative statements (ebastine poor/low, C24, C28) are not threshold-specific and are outweighed by the measured ~40% (C02).",
      "card_ids": ["C02", "C24", "C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C33", "C35", "C38", "C48", "C53", "C54", "C65", "C78"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute-bioavailability measurement for the query molecule itself is present in the supplied records.",
    "L3 AUC/Cmax records for mosapride and renzapride lack matched IV comparators, so they cannot be converted to absolute F values.",
    "No query-specific solubility, permeability, first-pass extraction, or efflux data are available.",
    "Transfer from mosapride/renzapride is based on structural analogy rather than an exact match.",
    "Ebastine qualitative low/poor statements (C24, C28) are not threshold-specific and do not affirm F<20%."
  ],
  "decision_summary": "L3 oral-exposure records for close benzamide analogs (mosapride, renzapride) show measurable oral absorption and are consistent with the prior high prediction; no threshold-relevant low-F evidence appears. Prediction remains high (F>=20%) with moderate confidence."
}

